value.período_atual:
={{ (() => {
  try {
    const p = JSON.parse($('Contexto Transação').item.json.payload_completo || '{}');
    const map = { mensal: 1, bimestral: 2, trimestral: 3, semestral: 6, anual: 12 };
    const m = Number(p.periodo_meses);
    if (Number.isFinite(m) && m > 0) return String(m);
    const slug = String(p.plano || '').toLowerCase();
    if (map[slug]) return String(map[slug]);
    const ref = String(p.external_ref || p.external_reference || $('Contexto Transação').item.json.external_ref || '');
    const mm = ref.match(/^lp-([a-z]+)-/i);
    if (mm && map[mm[1]]) return String(map[mm[1]]);
  } catch (e) {}
  return '1';
})() }}

