value.plano_slug:
={{ (() => {
  try {
    const p = JSON.parse($('Contexto Transação').item.json.payload_completo || '{}');
    const slug = String(p.plano || '').toLowerCase();
    if (slug && ['mensal','bimestral','trimestral','semestral','anual'].includes(slug)) return slug;
    const ref = String(p.external_ref || p.external_reference || '');
    const mm = ref.match(/^lp-([a-z]+)-/i);
    if (mm) return mm[1];
  } catch (e) {}
  return 'mensal';
})() }}

