parameters.jsCode:
const raw = $json ?? {};
const err = raw.error ?? raw;
const wfName = $workflow?.name || 'Workflow sem nome';
const wfId = $workflow?.id || 'N/A';
const execId = $execution?.id || 'N/A';
const now = new Date().toISOString();
const nodeFromError = err?.node?.name || err?.context?.nodeName || raw?.node?.name || 'Nao identificado';
const message = err?.message || raw?.message || 'Erro sem mensagem';
const code = err?.code || err?.name || raw?.code || 'N/A';
const details = (err?.description || err?.stack || raw?.description || '')
  .toString()
  .slice(0, 900);
const telegramText = [
  'ALERTA DE ERRO NO FLUXO',
  `Workflow: ${wfName}`,
  `Workflow ID: ${wfId}`,
  `Execucao ID: ${execId}`,
  `No: ${nodeFromError}`,
  `Codigo: ${code}`,
  `Mensagem: ${message}`,
  details ? `Detalhes: ${details}` : null,
  `Horario: ${now}`,
].filter(Boolean).join('\n');
return [{ json: { ...raw, telegram_text: telegramText } }];
